import { readFile } from "node:fs/promises";

export async function normalizeFixture(path) {
  return projectFixture(JSON.parse(await readFile(path, "utf8")));
}

export function projectFixture(fixture) {
  requireEnvelope(fixture);
  const base = {
    schemaVersion: "ji-pi-projection-v1",
    fixtureId: fixture.fixtureId,
    domain: fixture.domain,
    sourceRevision: fixture.source.revision,
  };
  const projection = switchDomain(fixture);
  return sortObject({ ...base, ...projection });
}

function switchDomain(fixture) {
  switch (fixture.domain) {
    case "provider":
      return projectProvider(fixture);
    case "agent-loop":
      return projectAgentLoop(fixture);
    case "session":
      return projectSession(fixture);
    case "compaction":
      return projectCompaction(fixture);
    case "protocol":
      return projectProtocol(fixture);
    default:
      throw new Error(`unknown Pi fixture domain: ${fixture.domain}`);
  }
}

function projectProvider(fixture) {
  const events = fixture.raw.events;
  requireArray(events, "provider raw.events");
  const eventTypes = events.map((event) => event.type);
  if (!eventTypes.includes("toolcall_end") || !eventTypes.includes("done")) {
    throw new Error("provider fixture must contain a completed tool call stream");
  }
  return {
    request: {
      messages: fixture.input.context.messages,
      toolSchemas: fixture.input.context.tools,
      modelOptions: fixture.input.modelOptions,
    },
    stream: events.map((event) => pickDefined(event, [
      "type", "contentIndex", "delta", "content", "toolCall", "reason", "partial", "message", "error",
    ])),
    result: fixture.raw.finalMessage,
    providerState: fixture.raw.providerState,
  };
}

function projectAgentLoop(fixture) {
  const events = fixture.raw.events;
  const messages = fixture.raw.messages;
  requireArray(events, "agent-loop raw.events");
  requireArray(messages, "agent-loop raw.messages");
  const eventTypes = events.map((event) => event.type);
  if (!eventTypes.includes("tool_execution_start") || !eventTypes.includes("tool_execution_end")) {
    throw new Error("agent-loop fixture must execute a tool");
  }
  return {
    events: events.map((event) => {
      const projected = pickDefined(event, ["type", "toolCallId", "toolName", "args", "result", "isError"]);
      if (event.message !== undefined) projected.messageRole = event.message.role;
      if (event.assistantMessageEvent !== undefined) projected.assistantEventType = event.assistantMessageEvent.type;
      if (event.messages !== undefined) projected.messageRoles = event.messages.map((message) => message.role);
      if (event.toolResults !== undefined) projected.toolResultRoles = event.toolResults.map((message) => message.role);
      return projected;
    }),
    messages,
  };
}

function projectSession(fixture) {
  const log = fixture.raw.log;
  requireArray(log, "session raw.log");
  for (let index = 0; index < log.length; index++) {
    const item = log[index];
    if (item.seq !== index + 1) throw new Error("session log sequence must be contiguous");
    if (item.kind === "entry" && item.entry?.seq !== item.seq) throw new Error("entry wrapper sequence mismatch");
    if (item.kind === "record" && item.record?.seq !== item.seq) throw new Error("record wrapper sequence mismatch");
  }
  const entryRoles = log
    .filter((item) => item.kind === "entry" && item.entry.type === "message")
    .map((item) => item.entry.message.role);
  if (JSON.stringify(entryRoles) !== JSON.stringify(["user", "assistant", "toolResult"])) {
    throw new Error("session fixture must preserve Pi message roles");
  }
  return {
    log,
    leafId: fixture.raw.leafId,
    openOperationIds: fixture.raw.openOperations.map((operation) => operation.id),
    logKinds: log.map((item) => item.kind),
    entryRoles,
  };
}

function projectCompaction(fixture) {
  const preparation = fixture.raw.preparation;
  if (!preparation || !Array.isArray(preparation.retainedTail)) {
    throw new Error("compaction fixture must contain Pi preparation output");
  }
  return {
    settings: preparation.settings,
    messagesToSummarize: preparation.messagesToSummarize,
    turnPrefixMessages: preparation.turnPrefixMessages,
    retainedTail: preparation.retainedTail,
    isSplitTurn: preparation.isSplitTurn,
    tokensBefore: preparation.tokensBefore,
    previousSummary: preparation.previousSummary ?? null,
    fileOps: preparation.fileOps,
    rebuiltContext: fixture.raw.context,
    tokenEstimates: fixture.raw.tokenEstimates,
    serializedConversation: fixture.raw.serializedConversation,
  };
}

function projectProtocol(fixture) {
  const raw = fixture.raw;
  if (raw.frameHex !== fixture.assertion.frameHex || raw.payloadHex !== fixture.assertion.payloadHex) {
    throw new Error("protocol wire bytes differ from the pinned Pi assertion");
  }
  if (raw.decoded.length !== 1) throw new Error("protocol fragmented decode must yield one message");
  return {
    parsed: raw.parsed,
    decoded: raw.decoded,
    payloadHex: raw.payloadHex,
    frameHex: raw.frameHex,
    frameBase64: raw.frameBase64,
  };
}

function requireEnvelope(fixture) {
  if (fixture.schemaVersion !== "1.0" || typeof fixture.fixtureId !== "string" || typeof fixture.domain !== "string") {
    throw new Error("invalid Pi fixture envelope");
  }
  if (fixture.source?.repository !== "https://github.com/earendil-works/pi.git"
